import React from 'react';

const Portfolio = () => {
  return (
    <div style={styles.container}>
      <header style={styles.header}>RD/>&nbsp;</header>
      <main style={styles.main}>
        <h1 style={styles.name}>Ranvir Deshmukh</h1>
        <p style={styles.description}>I'm currently building Pointer.</p>
        <p style={styles.description}>
          Previously, I built <span style={styles.highlight}>Secant</span>, <span style={styles.highlight}>Codin</span> (acquired), and <span style={styles.highlight}>Codology</span>.
        </p>
        <div style={styles.links}>
          <a href="#" style={styles.link}>LinkedIn</a>
          <span style={styles.separator}>X</span>
          <a href="#" style={styles.link}>Github</a>
        </div>
      </main>
    </div>
  );
};

const styles = {
  container: {
    fontFamily: "Arial, sans-serif",
    color: "#000",
    backgroundColor: "#fff",
    margin: 0,
    padding: 0,
    minHeight: "100vh",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
  },
  header: {
    fontSize: "20px",
    fontWeight: "bold",
    position: "absolute",
    top: "10px",
    left: "10px",
  },
  main: {
    textAlign: "center",
    padding: "0 20px",
  },
  name: {
    fontSize: "48px",
    fontWeight: "bold",
    margin: "10px 0",
  },
  description: {
    fontSize: "16px",
    margin: "10px 0",
  },
  highlight: {
    fontWeight: "bold",
  },
  links: {
    marginTop: "20px",
  },
  link: {
    textDecoration: "none",
    color: "#000",
    fontWeight: "bold",
    margin: "0 10px",
  },
  separator: {
    margin: "0 10px",
  },
};

export default Portfolio;
